import { execSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const src = execSync('git -C /home/user/Claudinite show HEAD~1:packs/basics/RULES.md', { encoding: 'utf8' });
const orig = src.slice(src.indexOf('# Engineering practices')).split('\n')
  .filter((l) => l.startsWith('- ')).map((l) => l.slice(2));

// One block per situation. `covers` lists the original bullets (1-based) it absorbs.
const blocks = [
  { covers: [1], text: '**Naming a file, module, or symbol** — name it for its scope or responsibility, not the technology or mechanism behind it.' },

  { covers: [2], text: '**Referring to a value from more than one place** — prefer a shared constant or a reference over copying it, and generate derived data rather than hand-maintaining it. If you can\'t, add a drift guard: the generic `sharedConstants` check for a plain value, or one that runs the real logic against the copy in both directions when the duplicate mirrors matcher or predicate logic. Have the guard\'s own text name the places it watches and why the split is forced, and don\'t also comment the duplication — the guard covers it.' },

  { covers: [3], text: '**Writing file A so it depends on file B** — say what A needs from B, or that it delegates, and don\'t re-spell how B does its job. If you\'re about to paraphrase B\'s procedure, point at B instead. This holds for code comments and Markdown alike.' },

  { covers: [4], text: '**Committing** — one concern per commit: if two changes could each stand alone, split them, and a message that wants numbered items is the split talking. Once a commit has landed, revise with a new commit, never a rewrite of that one.' },

  { covers: [5], text: '**Working with a file a test or tool generates** — put `GENERATED` in its name, and don\'t hand-edit it; change the generator. Never resolve its merge conflict by hand: clear the markers with either side, re-run the generator against the merged inputs, and commit that output. Consider automating the clear with a `merge=ours` `.gitattributes` entry, and `git rerere` for a conflict that recurs.' },

  { covers: [6], text: '**Relying on how a platform or runtime behaves** — verify it against authoritative docs or a real run, not a comment or a prior commit\'s claim.' },

  { covers: [7], text: '**Optimising** — if the change is meant to preserve behaviour, prove it: hash the full outputs of both paths across every branch, fuzzing the inputs that select each, and accept only a bit-identical match. If the correctness risk outweighs the speed-up, leave the path alone and record that as a deliberate call.' },

  { covers: [8], text: '**Needing a library for a narrow job** — prefer a built-in, or a few lines. When the assumption that justified an existing dependency lapses, drop it.' },

  { covers: [9], text: '**Answering an edge case a review raised** — first check whether the existing composed rules already produce the right answer. If they do, add no production code: pin it with a regression test that asserts the contrast case too, plus an accept criterion where you track those.' },

  { covers: [10], text: '**Documenting a procedure** — read the authoritative external docs first and write only what they don\'t carry: our failure modes, gotchas, the exact path we ran. Don\'t document or recommend a path you haven\'t run, however standard it looks.' },

  { covers: [11, 12], text: '**Writing code that can silently do nothing** — a swallowed error, a best-effort fallback, a probe-gated optimisation, a hint the runtime may ignore — record which path actually ran, reading the state back where the platform exposes it. During development, before the solution is proven right, add that debugging information first and remove it later. Without the record, a run where the capability never engaged is indistinguishable from one where it did and didn\'t help.' },

  { covers: [13], text: '**Persisting anything on a user\'s machine** — put it under the one user-deletable location, and extend that location rather than earn a second one. If the platform forces something outside it, a registration the OS owns, name that explicitly as the exception.' },

  { covers: [14], text: '**Changing what the software does with a user\'s data** — the permission string, privacy policy and store listing are part of the contract, so change them in the same commit. Retaining something new, opening a listener or adding an outbound connection changes the promise rather than adding a field: decide it explicitly and rewrite the disclosure before the code. Expect the claim in more than one place — grep the whole surface for the standing absolutes it touches ("no tracking", "no cookies", "no external assets") and reconcile every hit.' },

  { covers: [15], text: '**Driving an external runtime more than once in a session** — a headless browser, a device, a REPL, a deploy target — write one parameterised driver into the scratchpad, taking the target, the selector and the output path from argv, and re-point it rather than author a throwaway per invocation.' },

  { covers: [16], text: '**Automating something that needs live conversation context** — hook it to an existing human workflow event rather than background infrastructure; shell hooks have no conversation access and fire per turn, not at session end. Consider changing an existing command\'s definition — usually the cheapest trigger.' },

  { covers: [17], text: '**Writing the exit path of a pipeline or CI step** — an expected, handled outcome exits clean with a comment. Reserve non-zero for genuine breakage.' },

  { covers: [18], text: '**A fetch that works locally but fails from CI or a sandbox** — a 403/400 or a CAPTCHA wall is the datacenter IP, not the User-Agent, and headers won\'t change it. Route it through a residential proxy, which usually renders JS too. If it stays blocked through the proxy, treat the target as un-cacheable.' },

  { covers: [19], text: '**Killing a process by pattern** — `pkill -f` matches the invoking shell\'s own command line too, so never chain it, and bracket one character of the pattern (`[h]ttp.server 8099`) to break the self-match.' },

  { covers: [20, 21], text: '**Working in a fresh checkout or sandbox** — a setup script may start in the repo\'s parent rather than the checkout, so `cd` in before running anything. A `Cannot find module` there is usually an install that hasn\'t run yet, not a code bug: install and re-run before hunting for a code-level cause.' },

  { covers: [22, 23], text: '**Deciding where a config value or a classification lives** — avoid a default; require the value explicitly, or make it structural, derived from where the thing lives. Prefer a structural classifier to a hand-set field, and collapse a property tracked in several places into one. When automation maintains many copies of a config, have it materialize the explicit value into every file it maintains instead of interpreting absence.' },

  { covers: [24], text: '**Handling a value that can be unknown** — unknown is a state of its own: never encode it as a zero, an empty string or a type\'s default, and don\'t let a decoder collapse it into one. Keep it a missing key or an explicit null, keep the zero for a real zero, and preserve all three states at every stage of a pipeline. Treat absence as a permanent shape of the data rather than a gap to close, and where two fields claim the same fact, let each mean what its own source said and leave the call to the consumer.' },

  { covers: [25, 26], text: '**Writing a check that scans the repo** — take the file set from `git ls-files` rather than a filesystem walk with paths to skip, and remember a brand-new file is untracked until you add it, so a green run isn\'t coverage of it. When scanning for a forbidden token, strip comments first so it matches code, not prose — string-aware, since a `//` inside a URL is not a comment. Reuse `stripComments` from [`engine/checks/helpers/code-scanning.mjs`](../../engine/checks/helpers/code-scanning.mjs); if the scan can\'t import it, inline the same pass and point a comment back at that source.' },

  { covers: [27, 28, 29], text: '**Writing a comment** — carry the why, or a cross-file relationship the code can\'t state itself; if the code plus a known convention already says it, write nothing. Describe the current state, never the edit that produced it: don\'t explain the change you just made, and don\'t note what was removed or renamed. If a comment narrates a past fix, keep only the part still true of the code in front of you. When it must name a path, spell that path in one canonical place and point every other mention there.' },
];

// structural checks
const covered = blocks.flatMap((b) => b.covers);
if (covered.length !== orig.length || new Set(covered).size !== orig.length) {
  throw new Error(`blocks cover ${new Set(covered).size} of ${orig.length} originals`);
}
if (covered.some((n, i) => i > 0 && n < covered[i - 1])) throw new Error('blocks are out of source order');
if (!blocks.every((b) => /^\*\*.+?\*\* — /.test(b.text))) throw new Error('a block lacks a bolded situation');

// A block may say "never" only where a bullet it covers says it.
const escalated = blocks.filter((b) => /\bnever\b/i.test(b.text) && !b.covers.some((n) => /\bnever\b/i.test(orig[n - 1])));
if (escalated.length) throw new Error(`modality escalated: ${escalated.map((b) => b.covers).join(' ')}`);

const cell = (s) => s.replace(/\|/g, '\\|');
const rows = [];
blocks.forEach((b, i) => {
  b.covers.forEach((n, j) => {
    rows.push(`| ${j === 0 ? i + 1 : ''} | ${cell(orig[n - 1])} | ${j === 0 ? cell(b.text) : ''} |`);
  });
});

const words = (a) => a.reduce((s, x) => s + x.replace(/[*`_]/g, '').split(/\s+/).filter(Boolean).length, 0);
const [ow, bw] = [words(orig), words(blocks.map((b) => b.text))];

const doc = `# Engineering practices — original vs situation blocks

Every rule in the \`# Engineering practices\` section of \`packs/basics/RULES.md\`, regrouped by situation.

| Column | What it is |
|---|---|
| **Original** | The text as it stands in \`main\` — verbatim, 29 bullets, ${ow} words. |
| **Rewritten** | ${blocks.length} situation blocks, ${bw} words. |

**One row per original bullet.** Where a block absorbs several originals, each gets its own row and the Rewritten cell is filled on the first; the rows beneath it belong to that same block.

## The shape

Each block opens with **the situation the reader is in**, then walks a decision:

> **\`<the situation>\`** — \`<what to do by default>\`. If you can't, \`<the fallback>\`. Consider \`<the optional aid>\`, and don't \`<the thing the other rules make unnecessary>\`.

Three things follow from grouping by situation rather than by rule:

- **A reader arrives with a problem, not a rule number.** Having found the block, they have the whole decision in front of them, not a cross-reference to three neighbouring bullets.
- **The cascade carries the modality.** \`prefer\` is the default path, \`if you can't\` gates the fallback, \`consider\` marks an aid, \`don't\` closes off what the earlier clauses make unnecessary. No clause has to borrow another's strength.
- **Naming a mechanism replaces describing it.** Where a block names a check, a helper or a git setting, the parameters live with that thing, not here.

## What moved out of the rules and into the named mechanism

Applying your depth to the whole document means these specifics are no longer in the prose. Each is recoverable from the thing the block names — but if you want any back, they're the ones to pull.

| Block | No longer stated | Now lives with |
|---|---|---|
| 2 | \`.claudinite-checks.json\` as the config path; the \`value\` / \`counts\` / \`what\` fields | the \`sharedConstants\` check |
| 2 | counts match the *flat* literal, so keep a guarded value on one line | the \`sharedConstants\` check's failure message |
| 2 | \`regex: true\` plus a pattern, for a value that changes over time | the \`sharedConstants\` check's options |
| 5 | the example filenames \`foo.GENERATED.md\`, \`foo.baseline.GENERATED.json\` | the naming rule itself |
| 5 | the one-time \`git config merge.ours.driver true\` per clone; \`git config rerere.enabled true\` | \`git\` docs |
| 9 | "sometimes on more than one independent count" | — dropped as rationale |
| 13 | the \`<meta>\` / marketing / README / source-header enumeration | — dropped as example |
| 19 | "everything after the \`;\` or \`&&\` is silently dropped" | — dropped as rationale |
| 20 | "a bare \`npm ci\` finds no manifest and silently does nothing" | — dropped as rationale |
| 20 | \`x || DEFAULT\` and its comment; the fleet-baselining \`"delivery": "auto"\` example | — dropped as example |
| 22 | "the run's own 'checked N files' line is not evidence" | — folded into "a green run isn't coverage" |
| 22 | "deleting to end-of-line corrupts real code"; the \`// saved in chrome.storage\` example | — dropped as rationale and example |

## Length

| | Units | Words |
|---|---|---|
| Original | 29 bullets | ${ow} |
| Rewritten | ${blocks.length} blocks | ${bw} |

${Math.round(((ow - bw) / ow) * 100)}% shorter than the original, in ${blocks.length} blocks instead of 29 bullets — so each block is longer than a bullet was, and there are fewer places to look.

---

| Block | Original | Rewritten |
|---|---|---|
${rows.join('\n')}
`;

writeFileSync('/tmp/claude-0/-home-user-Claudinite/b84e66b0-dfc5-5cb9-8995-875ae87eb107/scratchpad/engineering-practices-blocks.md', doc);
console.log(`${blocks.length} blocks over ${orig.length} originals, ${rows.length} rows, ${ow}w -> ${bw}w`);

