import { readFileSync, writeFileSync } from 'node:fs';

const RULES = '/home/user/Claudinite/packs/basics/RULES.md';
const LIMIT = 100;

// ---------- unwrap: collapse a wrapped file back to one logical line per unit
const unwrap = (text) => {
  const out = [];
  let cur = null;
  const flush = () => { if (cur !== null) { out.push(cur); cur = null; } };
  for (const raw of text.split('\n')) {
    if (!raw.trim()) { flush(); out.push(''); continue; }
    if (/^#/.test(raw)) { flush(); out.push(raw); continue; }
    if (/^- /.test(raw)) { flush(); cur = raw; continue; }
    if (/^\d+\. /.test(raw)) { flush(); cur = raw; continue; }
    if (cur === null) cur = raw;
    else cur += ' ' + raw.trim();
  }
  flush();
  // collapse runs of blank lines
  return out.filter((l, i) => l !== '' || out[i - 1] !== '');
};

// ---------- wrap: break a logical line at LIMIT bytes without splitting atoms
const tokenize = (text) => {
  const out = [];
  const atom = /`[^`]*`|\[[^\]]*\]\([^)]*\)/g;
  let last = 0;
  for (const m of text.matchAll(atom)) {
    if (m.index < last) continue;
    out.push(...text.slice(last, m.index).split(' ').filter(Boolean));
    const before = out.length && !/\s$/.test(text.slice(0, m.index)) ? out.pop() : '';
    const tail = text.slice(m.index + m[0].length).match(/^[^\s]+/);
    const after = tail ? tail[0] : '';
    last = m.index + m[0].length + after.length;
    out.push(before + m[0] + after);
  }
  out.push(...text.slice(last).split(' ').filter(Boolean));
  return out;
};

const wrap = (body, first, cont) => {
  const lines = [];
  let line = first;
  let fresh = true;
  for (const tok of tokenize(body)) {
    if (!fresh && Buffer.byteLength(line + ' ' + tok) > LIMIT) {
      lines.push(line);
      line = cont + tok;
    } else {
      line = fresh ? line + tok : line + ' ' + tok;
      fresh = false;
    }
  }
  lines.push(line);
  return lines;
};

const render = (logical) => {
  const out = [];
  logical.forEach((l, i) => {
    if (l === '' || /^#/.test(l)) { out.push(l); return; }
    const m = l.match(/^(- |\d+\. )/);
    if (m) {
      // blank line between consecutive list items, for human reading
      if (out.length && out[out.length - 1] !== '' && /^(- |\d+\. |\s)/.test(String(logical[i - 1]))) out.push('');
      out.push(...wrap(l.slice(m[1].length), m[1], ' '.repeat(m[1].length)));
    } else {
      out.push(...wrap(l, '', ''));
    }
  });
  return out.join('\n').replace(/\n{3,}/g, '\n\n') + '\n';
};

// ---------- the rewritten head: Working discipline + The task lifecycle
const head = [
  '# Working discipline',
  '',
  "The working discipline that isn't itself a GitHub operation — general habits for how to approach a change, independent of any one project.",
  '',
  '- **Starting any requested change** — begin from the *problem*, not the solution, in any repository and not just this one. Reach an explicit shared understanding with the owner of the problem the change is meant to solve **and** agreement that the requested change is the best way to solve it; a different fix, or no change at all, may serve the underlying problem better.',
  '- **Replying to an owner comment** — open with an explicit classification line, `Comment class: correction | feature | process-change | other`, where `other` covers questions, approvals and command phrases and a mixed comment names each part. The class decides where the change lands and what must exist before any fix.',
  '- **An automation dispatch prompt** — it is a comment too: classify it, class `other`, in your *first* substantive reply rather than at the end of the run.',
  '- **Writing that classification line** — put the class **alone on it** and any explanation on the next line. The line is scanned for *every* class token on it, so restating the menu to rule options out ("not a correction, feature request, or process-change") declares all of them and arms the gates those classes carry.',
  '- **A class you have declared** — it cannot be taken back. The transcript is append-only, and a clean re-declaration further down does not override the first.',
  '- **Classified a correction** — you misunderstood something. Repair the shared understanding, then rework what the misread already touched; the artifact changes as much as the correction demands, but a correction never adds a new requirement or rule.',
  '- **Classified a feature** — agree on the requirement, record it in the project\'s requirements document (its executable spec, where it keeps one), write the test that proves it and watch it fail, then implement until it passes.',
  '- **Classified a process change** — the owner is changing *how* work is done. Land it as durable rules in the project\'s local scope, its own local packs (in Claudinite itself, its packs), routed through the mechanism promotion ladder (platform setting → hook → check → skill → prose). Promoting a rule into the shared canon is the growth lifecycle\'s separate call, not the interactive session\'s.',
  '- **Choosing what goes on that ladder** — only a rule that constrains *how work is done* and outlives any one feature; a checkable signature doesn\'t earn a rule its place.',
  '- **Two rule shapes to reject outright** — a check that asserts particular code exists or still reads a particular way (it pins a point in time, dies with the code it pins, and constrains no later change), and a rule derivable from the product\'s requirements (that is a requirement — take it to the feature path, the requirements document and the test that proves it).',
  '- **Landing a rule anywhere on the ladder** — author the assurance first, the check the future world must satisfy, execute it and watch it fail, and only then make the fixes that turn it green.',
  '- **Landing a rule at the prose rung** (an in-flight judgment rule no check can carry) — the equivalent step is showing the corpus doesn\'t already cover the rule before writing it.',
  '- **Both build paths** — they share one spine: state the expectation in its durable home first, watch it fail against the current world, then change the world to satisfy it. A fix made before its assurance exists can never show it addressed what the owner actually asked for.',
  '- **Building a mechanism for a behavior** — verify against a real run that it isn\'t already provided.',
  '- **Release, deploy, versioning or CI plumbing** — look for the shared pack that owns it first; copying a mechanic from a sibling repo is the tell that it belongs centrally. If no pack owns it, report the gap rather than author a third copy that gets deleted later along with its reviewed workflow.',
  '- **Every task** — minimize its shelf-life, the time from starting it until everyone can forget about it. An open task is a standing tax: whoever returns to it pays a full reload of the context that was free while the work was hot.',
  '- **Finishing a change** — watch it work **now**; never park it on "check tomorrow", which is almost always the wrong choice in any context.',
  '- **Changing scheduled or unattended machinery** — force a run now (the scheduler\'s `FORCE_TASKS` lever, a `workflow_dispatch`, the fleet-wide force sweep) and watch it to a terminal state rather than wait for its next natural run. Those levers exist precisely so verification can happen while the change is still in someone\'s head.',
  '- **Planning a migration** — prefer the design that converges in one forced pass to the one that trickles across nightly cycles, accept legacy input at the door so nothing has to wait for stragglers, and drive the stragglers with a standing mechanism rather than a phase someone must remember to close.',
  '- **When verifying now is genuinely impossible** (an external release window, an upstream fix in flight) — make the follow-up a mechanism that comes to you: a scheduled task, a watched PR, an issue something converges. Never a human\'s memory.',
  '- **Feedback that flags a misunderstanding** — check whether the artifact is already correct before expanding it; if it is, say so and push back rather than edit. A misread doesn\'t imply the text is wrong.',
  '- **Writing anything** — size it to its idea: "open one issue" takes a sentence, not three paragraphs.',
  '- **Correcting or auditing an artifact against an authoritative source** — derive the corrected version from the *source* before reading the existing draft, then diff against the old draft to surface what was actually wrong. Reading the draft first anchors you to its framing and quietly carries its errors into your "fix".',
  '',
  'Three harness-tool contracts, before you spend a call rediscovering them:',
  '',
  '- **Searching for a tool with `ToolSearch`** — a search that finds nothing is evidence about your query, not about the environment: deferred tools are matched on keywords that aren\'t their own vocabulary, so a capability can sit in the session while the search denies it. Search the fully-qualified name (`select:mcp__<server>__<tool>`, copied off the deferred-tools listing) and try the tool before telling the owner a step is theirs — the bare short name returns "no matching tools", which reads exactly like absence.',
  '- **Calling `Edit`** — the file must have been read *with the read tool*; `cat`/`grep`/`sed` don\'t count, however much is already on screen. The moment shell output tells you which file you\'re about to change, read that exact path; a narrow offset window satisfies it.',
  '- **Needing exact text from the web** — a summarizing fetch tool is not a source: asked for exact text it returns a description, and ordinary publisher pages routinely `403`. When the bytes matter, `curl` into the scratchpad and read from disk. On a `403` don\'t retry and don\'t try a sibling URL — attribute the search snippet to the publisher instead of asserting it, and mark it for re-verification.',
  '',
  '- **A build, test or CI warning** — fix it rather than tolerate it, with a small, targeted fix that addresses the *cause* in the same change; a clean run makes a genuinely new warning or error stand out.',
  '- **Suppressing a warning** — muting it with a flag (e.g. `--disable-warning`), `eslint-disable`, swallowing it — is **not** a small fix and never the quick path. Reach for it only as a deliberate, reviewed decision once the real fix has been weighed and rejected.',
  '- **A suppression you do keep** — **carry its reason at the site**, on the suppression line or in the comment immediately above it, saying why the fix was rejected. That inline reason *is* the review record, so no second justification is recorded elsewhere.',
  '- **A finding on *text* rather than code** — try deleting the flagged phrase before waiving it; decoration often buys the coupling the rule exists to prevent for nothing, and a waiver is for a crossing that genuinely must exist.',
  '- **A sandbox or proxy denying a fetch** — treat it as a **policy boundary, not an obstacle to route around**: don\'t reach for an open-network runner, an ad-hoc CI workflow or a push-triggered "probe", to make the request from somewhere the policy doesn\'t apply. Answer from committed reference material or ask the owner, and say plainly that anything unverifiable is unverified.',
  '- **Working around a finding from a vendored check** — confirm the vendored copy is current first; it reflects its last refresh, not upstream\'s head, so the fix may already exist upstream and simply not be pulled in yet.',
  '- **A warning you can\'t fix now with a small cause-addressing change** (it waits on an upstream release, or the real fix is a larger refactor) — open a dedicated issue unless one is already open, then move on. Resolving it, by real fix or a consciously-chosen suppression, happens in that issue\'s own change.',
  '- **An approval — to merge, to ship, to proceed** — it applies only *backward*, to the work already in front of the owner when it\'s given, never to anything requested or done *after* it. A later follow-up, even a fix to the just-approved change, needs its own explicit approval.',
  '- **A chosen answer to a multiple-choice prompt** — it isn\'t authorization, even when an option\'s wording mentioned the action.',
  '',
  '# The task lifecycle',
  '',
  'The issue → branch → PR lifecycle every new task follows, independent of any one project. The rest of the git/GitHub procedures live in the `git-github-advanced` skill.',
  '',
  'For every new task:',
  '',
  '1. Create a GitHub issue describing the task before starting work.',
  '2. Develop on a branch; reference that issue number in commit messages (e.g. `Refs #123`, `Fixes #123`, or `Closes #123`).',
  '3. Update the issue\'s status (comments / close) as work progresses and when it\'s done.',
  '',
  '- **A step only a human can perform** (flipping a repository or console setting, granting a permission, adding a secret) — give it **its own issue**, never a note in the PR body: the note merges and disappears with the PR while the setting stays unflipped. The exception is a step whose home is an artifact the human is already editing.',
  '- **That issue** — give it a checkbox per step, what breaks while each is off, and its closing condition.',
  '- **Before handing a step over at all** — confirm you genuinely can\'t do it yourself.',
  '',
];

const current = unwrap(readFileSync(RULES, 'utf8'));
const cut = current.indexOf('# Engineering practices');
if (cut === -1) throw new Error('no Engineering practices heading');
const tail = current.slice(cut);

const next = render([...head, ...tail]);

// ---------- assertions
const bullets = (t) => t.filter((l) => l.startsWith('- '));
const before = bullets(tail);
const after = bullets(unwrap(next).slice(unwrap(next).indexOf('# Engineering practices')));
if (before.length !== after.length || before.some((b, i) => b !== after[i])) {
  throw new Error('Engineering practices blocks changed');
}
if (!next.includes('`Comment class: correction | feature | process-change | other`')) {
  throw new Error('the classification literal was lost');
}
const over = next.split('\n').filter((l) => Buffer.byteLength(l) > LIMIT);
if (over.length) throw new Error(`${over.length} line(s) over ${LIMIT}: ${over[0].slice(0, 70)}`);

writeFileSync(RULES, next);
const listItems = unwrap(next).filter((l) => /^- /.test(l)).length;
console.log(`${listItems} rules; longest line ${Math.max(...next.split('\n').map((l) => Buffer.byteLength(l)))} bytes`);

