const current = unwrap(readFileSync(RULES, 'utf8'));
const cut = current.indexOf('# Engineering practices');
if (cut === -1) throw new Error('no Engineering practices heading');
const tail = current.slice(cut);

const next = render([...head, ...tail]);

// ---------- assertions
const bullets = (t) => t.filter((l) => l.startsWith('- '));
const before = bullets(tail);
const after = bullets(unwrap(next).slice(unwrap(next).indexOf('# Engineering practices')));
if (before.length !== after.length || before.some((b, i) => b !== after[i])) {
  throw new Error('Engineering practices blocks changed');
}
if (!next.includes('`Comment class: correction | feature | process-change | other`')) {
  throw new Error('the classification literal was lost');
}
const over = next.split('\n').filter((l) => Buffer.byteLength(l) > LIMIT);
if (over.length) throw new Error(`${over.length} line(s) over ${LIMIT}: ${over[0].slice(0, 70)}`);

writeFileSync(RULES, next);
const listItems = unwrap(next).filter((l) => /^- /.test(l)).length;
console.log(`${listItems} rules; longest line ${Math.max(...next.split('\n').map((l) => Buffer.byteLength(l)))} bytes`);

