import { execSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';

const unwrap = (text) => {
  const out = [];
  let cur = null;
  const flush = () => { if (cur !== null) { out.push(cur); cur = null; } };
  for (const raw of text.split('\n')) {
    if (!raw.trim()) { flush(); out.push(''); continue; }
    if (/^#/.test(raw)) { flush(); out.push(raw); continue; }
    if (/^(- |\d+\. )/.test(raw)) { flush(); cur = raw; continue; }
    if (cur === null) cur = raw; else cur += ' ' + raw.trim();
  }
  flush();
  return out.filter(Boolean);
};

const old = execSync('git -C /home/user/Claudinite show origin/main:packs/basics/RULES.md', { encoding: 'utf8' });
const now = readFileSync('/home/user/Claudinite/packs/basics/RULES.md', 'utf8');
const oldUnits = unwrap(old.slice(0, old.indexOf('# Engineering practices')));
const newHead = unwrap(now.slice(0, now.indexOf('# Engineering practices')));

// The 20 rule-bearing units of the original head, in source order, identified by
// their opening words. Framing prose (section intros, "For every new task:") and
// the three lifecycle steps are excluded — they are unchanged.
const opens = [
  'Start every requested change',
  'Open your reply to an owner comment',
  '1. **A correction**',
  '2. **A feature**',
  '3. **A process change**',
  'The two build modes share one spine',
  'Before building a mechanism for a behavior',
  "**Minimize every task's shelf-life",
  'When feedback flags a misunderstanding',
  'When correcting or auditing an artifact',
  '- **A `ToolSearch` that finds nothing',
  '- **`Edit` requires the file',
  '- **A summarizing fetch tool is not a source',
  'Fix build/test/CI warnings',
  'Suppressing a warning',
  'A blocked host is a',
  'Before working around a finding from a vendored check',
  "When a warning can't be fixed",
  'An approval — to merge',
  'A step only a human can perform',
];
// how many rewritten rules each original unit became
const groups = [1, 4, 1, 1, 5, 1, 2, 5, 2, 1, 1, 1, 1, 1, 3, 1, 1, 1, 2, 3];

const originals = opens.map((o) => {
  const hit = oldUnits.filter((u) => u.startsWith(o));
  if (hit.length !== 1) throw new Error(`"${o}" matched ${hit.length} units`);
  return hit[0];
});
if (originals.some((u, i) => i > 0 && oldUnits.indexOf(u) < oldUnits.indexOf(originals[i - 1]))) {
  throw new Error('units are out of source order');
}

const rules = newHead.filter((l) => l.startsWith('- '));
const total = groups.reduce((a, b) => a + b, 0);
if (rules.length !== total) throw new Error(`${rules.length} rewritten rules vs ${total} claimed`);

const cell = (s) => s.replace(/\|/g, '\\|').replace(/^(- |\d+\. )/, '');
const rows = [];
let k = 0;
groups.forEach((size, g) => {
  for (let i = 0; i < size; i++) {
    rows.push(`| ${i === 0 ? g + 1 : ''} | ${i === 0 ? cell(originals[g]) : ''} | ${cell(rules[k++])} |`);
  }
});

const w = (a) => a.reduce((s, x) => s + x.replace(/[*`_]/g, '').split(/\s+/).filter(Boolean).length, 0);
const [ow, nw] = [w(originals), w(rules)];
const splits = groups.filter((n) => n > 1).length;

const doc = `# Working discipline & task lifecycle — original vs rewritten

The two sections of \`packs/basics/RULES.md\` outside Engineering practices, which was compared
separately.

| Column | What it is |
|---|---|
| **Original** | The rule-bearing prose as it stands in \`origin/main\` — verbatim, 20 units, ${ow} words. |
| **Rewritten** | ${rules.length} situation blocks, ${nw} words. |

**One row per rewritten rule.** Where a block absorbs one original unit's several rules, each gets a
row and the Original cell is filled on the first; the blank cells beneath belong to that same unit.

Excluded because they are unchanged: both section intros, the \`For every new task:\` lead-in, and
the three numbered lifecycle steps. The \`Three harness-tool contracts\` lead-in became a
\`## Harness-tool contracts\` heading — see the note below.

## What this pass actually did

Unlike the Engineering practices pass, **this one cut almost nothing**. It is decomposition: ${splits}
of the 20 original units were carrying more than one rule apiece in a single paragraph, and they
became ${rules.length - (20 - splits)} rules between them.

| | Units | Words |
|---|---|---|
| Original | 20 | ${ow} |
| Rewritten | ${rules.length} | ${nw} |

The text grows ${Math.round(((nw - ow) / ow) * 100)}%. Every rule now carries a bolded subject naming
its situation, and that costs more than the rationale removed — this is a re-shaping for findability,
not a compression. If you want the head to shrink as well, the lever is the same one used on
Engineering practices: cut the consequence clauses back to the ones a reader needs under pressure.

The two paragraphs that were doing the most work:

- **The classification paragraph** held four rules — the line itself, the automation-dispatch case,
  how to write the line, and its irreversibility. A reader who needed only the third had to read all
  four.
- **The shelf-life paragraph** held five — the principle, watching a change work now, forcing a
  scheduled run, migration planning, and the fallback when verifying now is impossible.

## Judgement calls

- **The class taxonomy lost its numbering.** The three classes were a numbered list, and the
  process-change rule referred to "mode 2". They are now \`**Classified a correction**\`,
  \`**Classified a feature**\` and \`**Classified a process change**\`, and the self-reference reads
  "take it to the feature path". Nothing outside \`RULES.md\` referenced the numbering.
- **\`Three harness-tool contracts\` became a heading.** With a blank line between every rule, three
  consecutive bullets no longer read as one run, so a lead-in promising three items pointed at
  nothing visible. They sit under \`## Harness-tool contracts\` instead.
- **The lifecycle's numbered steps stayed tight** — no blank lines between them. They are one ordered
  procedure rather than three rules, and spacing them made a three-line list look like three separate
  policies.
- **"Both build paths" replaced "The two build modes"** — "mode" was the numbered list's vocabulary
  and stopped making sense once the numbering went.

## Preserved deliberately

Every operative detail the checks pointing at this file depend on: the exact
\`Comment class: correction | feature | process-change | other\` literal, the alone-on-the-line
scanning rule and what restating the menu does, the three classes' obligations, and the issue
reference forms (\`Refs #123\`, \`Fixes #123\`, \`Closes #123\`).

Also kept, as exceptions that change what a reader does rather than reassure: a correction never
adds a new requirement or rule; a checkable signature doesn't earn a rule its place; the two rule
shapes to reject; the prose rung's substitute for the assurance step; the exception for a human step
whose home is an artifact the human is already editing.

---

| # | Original | Rewritten |
|---|---|---|
${rows.join('\n')}
`;

writeFileSync('/tmp/claude-0/-home-user-Claudinite/b84e66b0-dfc5-5cb9-8995-875ae87eb107/scratchpad/rules-head-comparison.md', doc);
console.log(`${rules.length} rules over 20 units, ${rows.length} rows, ${ow}w -> ${nw}w`);

